package com.playtimetracker;

import java.lang.reflect.Field;
import java.lang.reflect.Method;

/**
 * Drives {@link PlayTimePlugin#applyExternalBaseline} the way a real session does — tracked time
 * advancing one tick at a time against a game total that only moves in whole minutes — and checks
 * that no off-client time is reported for an account that never left the client.
 *
 * <p>This is the 47s bug: reported raw, the minute-quantised baseline leaves up to a minute of
 * phase difference that looks like mobile play.
 */
public class ExternalNoise
{
	public static void main(String[] args) throws Exception
	{
		final PlayTimePlugin plugin = new PlayTimePlugin();
		final Field cfg = PlayTimePlugin.class.getDeclaredField("config");
		cfg.setAccessible(true);
		cfg.set(plugin, new PlayTimeConfig()
		{
		});

		final Method apply = PlayTimePlugin.class
			.getDeclaredMethod("applyExternalBaseline", long.class);
		apply.setAccessible(true);

		final String todayKey = plugin.today().format(PlayTimePlugin.DATE_FORMAT);
		final PlayTimeRecord today = new PlayTimeRecord(todayKey, 0);
		plugin.records.put(todayKey, today);

		// A pre-existing account: 11 days of play before the plugin was installed.
		final long preInstallTrue = 11L * 24 * 60 * 100;

		long worstRaw = 0;
		long worstReported = 0;
		int nonZeroReports = 0;

		// 90 minutes of play, one tick at a time. Nothing happens off-client at any point.
		for (int tick = 1; tick <= 90 * 100; tick++)
		{
			today.setTime(tick);

			// The game's true total advances with us; the varc only exposes whole minutes.
			final long trueTotal = preInstallTrue + tick;
			final long reportedMinutes = trueTotal / TICKS_PER_MINUTE;
			apply.invoke(plugin, reportedMinutes * TICKS_PER_MINUTE);

			final long raw = raw(plugin);
			final long reported = plugin.getExternalSinceInstallTicks();
			worstRaw = Math.max(worstRaw, raw);
			worstReported = Math.max(worstReported, reported);
			if (reported > 0)
			{
				nonZeroReports++;
			}
		}

		System.out.println("90 minutes played, zero of it off-client:");
		System.out.printf("  worst raw OLD-PREINSTALL : %d ticks (%d s)%n",
			worstRaw, Math.round(worstRaw * 0.6));
		System.out.printf("  worst reported external  : %d ticks (%d s)%n",
			worstReported, Math.round(worstReported * 0.6));
		System.out.printf("  ticks reporting non-zero : %d of 9000%n", nonZeroReports);
		System.out.println(worstReported == 0
			? "  PASS - no phantom off-client time"
			: "  FAIL - still reporting phantom off-client time");

		// And a genuine 20 minutes off-client must still come through.
		final long trueTotal = preInstallTrue + 90 * 100 + 20 * 100;
		apply.invoke(plugin, (trueTotal / TICKS_PER_MINUTE) * TICKS_PER_MINUTE);
		final long real = plugin.getExternalSinceInstallTicks();
		System.out.printf("%nafter 20 real minutes off-client: reported %d ticks (%d min) - %s%n",
			real, real / TICKS_PER_MINUTE, real / TICKS_PER_MINUTE == 20 ? "PASS" : "CHECK");
	}

	private static final long TICKS_PER_MINUTE = 100L;

	private static long raw(final PlayTimePlugin p) throws Exception
	{
		final Method rt = PlayTimePlugin.class.getDeclaredMethod("recordTicks", String.class);
		rt.setAccessible(true);
		return (long) rt.invoke(p, PlayTimePlugin.EXTERNAL_TIME_KEY)
			- (long) rt.invoke(p, PlayTimePlugin.PRE_INSTALL_KEY);
	}
}

package com.playtimetracker;

import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.File;
import java.lang.reflect.Field;
import java.time.LocalDate;
import java.time.ZonedDateTime;
import java.util.Random;

/**
 * Renders {@link PlayTimeChart} straight to a PNG so its layout can be checked without launching
 * a client. Test-only: never shipped, and not referenced by the plugin.
 */
public class ChartRender
{
	public static void main(String[] args) throws Exception
	{
		final File out = new File(args.length > 0 ? args[0] : "chart-preview.png");

		// PlayTimeConfig is an interface whose methods all have defaults, so it can be
		// instantiated directly — no Guice, no client.
		final int days = args.length > 1 ? Integer.parseInt(args[1]) : 14;
		final PlayTimeConfig config = new PlayTimeConfig()
		{
			@Override
			public int chartDays()
			{
				return days;
			}
		};

		final PlayTimePlugin plugin = new PlayTimePlugin();
		final Field configField = PlayTimePlugin.class.getDeclaredField("config");
		configField.setAccessible(true);
		configField.set(plugin, config);

		// A fortnight of plausible play: a couple of blank days, one long session, one short.
		final LocalDate today = plugin.today();
		final Random random = new Random(7);
		for (int i = 0; i < config.chartDays(); i++)
		{
			final LocalDate date = today.minusDays(i);
			final long ticks;
			if (i == 3 || i == 9)
			{
				ticks = 0;
			}
			else if (i == 6)
			{
				ticks = 86_400;
			}
			else
			{
				ticks = 1_500 + random.nextInt(40_000);
			}
			if (ticks > 0)
			{
				final String key = date.format(PlayTimePlugin.DATE_FORMAT);
				plugin.records.put(key, new PlayTimeRecord(key, ticks));
			}
		}

		final PlayTimeChart chart = new PlayTimeChart(plugin);
		// PluginPanel is 225px wide; the chart gets that minus the stats panel's 12px borders.
		final int width = 201;
		final int height = 96;
		chart.setSize(width, height);
		chart.refresh();

		final BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
		chart.paint(image.getGraphics());
		ImageIO.write(image, "png", out);

		System.out.println("wrote " + out.getAbsolutePath());
		System.out.println("zone=" + plugin.zone() + " weekStartsOn=" + plugin.firstDayOfWeek()
			+ " today=" + today);

		System.out.println();
		System.out.println("::playtimedebug, no rollover seen yet:");
		for (String line : plugin.dayBoundaryLines())
		{
			System.out.println("  " + line);
		}

		// Simulate the client having watched the day turn over an hour early, which is the exact
		// symptom this command exists to expose.
		final Field at = PlayTimePlugin.class.getDeclaredField("lastRolloverAt");
		at.setAccessible(true);
		at.set(plugin, ZonedDateTime.now(plugin.zone()).toLocalDate()
			.minusDays(1).atTime(23, 0).atZone(plugin.zone()));
		final Field fromKey = PlayTimePlugin.class.getDeclaredField("lastRolloverFrom");
		fromKey.setAccessible(true);
		fromKey.set(plugin, today.minusDays(1).format(PlayTimePlugin.DATE_FORMAT));

		System.out.println();
		System.out.println("::playtimedebug, after an hour-early rollover:");
		for (String line : plugin.dayBoundaryLines())
		{
			System.out.println("  " + line);
		}
		System.out.println();

		for (final WeekStart ws : WeekStart.values())
		{
			final PlayTimePlugin p = new PlayTimePlugin();
			final Field f = PlayTimePlugin.class.getDeclaredField("config");
			f.setAccessible(true);
			f.set(p, new PlayTimeConfig()
			{
				@Override
				public WeekStart weekStart()
				{
					return ws;
				}
			});
			System.out.printf("  weekStart=%-22s -> %s%n", ws, p.firstDayOfWeek());
		}
	}
}

package com.playtimetracker;

import lombok.AllArgsConstructor;
import lombok.Data;

@Data
@AllArgsConstructor
public class PlayTimeRecord {
    private String date;
    private long time;

    public long getTime() {
        return time;
    }

    public void setTime(long time) {
        this.time = time;
    }

    public String getDate() {
        return date;
    }

    public void setDate(String date) {
        this.date = date;
    }
}

package com.playtimetracker;

import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

import javax.inject.Inject;
import java.awt.Dimension;
import java.awt.Graphics2D;

/**
 * Optional on-screen overlay showing any subset of the tracker's stats, chosen individually in config.
 */
class PlayTimeOverlay extends OverlayPanel
{
	private final PlayTimePlugin plugin;
	private final PlayTimeConfig config;

	@Inject
	private PlayTimeOverlay(PlayTimePlugin plugin, PlayTimeConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.overlayEnabled() || plugin.getSessionTicks() == 0 || plugin.getCurrentPlayer() == null)
		{
			return null;
		}

		panelComponent.getChildren().clear();

		addLine(config.overlaySession(), "Session", plugin.getSessionTicks());
		addLine(config.overlayToday(), "Today", plugin.getTodayTicks());
		addLine(config.overlayWeek(), "Week", plugin.getWeekTicks());
		addLine(config.overlayWeekAvg(), "Week avg/day", plugin.getWeekAvgTicks());
		addLine(config.overlayMonth(), "Month", plugin.getMonthTicks());
		addLine(config.overlayMonthAvg(), "Month avg/day", plugin.getMonthAvgTicks());
		addLine(config.overlayYear(), "Year", plugin.getYearTicks());
		addLine(config.overlayYearAvg(), "Year avg/day", plugin.getYearAvgTicks());
		addLine(config.overlayTotalTracked(), "Tracked", plugin.getTrackedTicks());
		addLine(config.overlayTrackedAvg(), "Tracked avg/day", plugin.getTrackedAvgTicks());
		addLine(config.overlayExternal(), "External", plugin.getExternalSinceInstallTicks());
		addLine(config.overlayTotalInGame(), "Total", plugin.getTotalTicks());

		if (panelComponent.getChildren().isEmpty())
		{
			return null;
		}

		panelComponent.getChildren().add(0, TitleComponent.builder().text("Play Time").build());
		return super.render(graphics);
	}

	private void addLine(boolean enabled, String label, long ticks)
	{
		if (!enabled)
		{
			return;
		}
		panelComponent.getChildren().add(LineComponent.builder()
				.left(label)
				.right(plugin.formatTicks(ticks))
				.build());
	}
}

package com.playtimetracker;

import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.PluginErrorPanel;
import net.runelite.client.ui.components.materialtabs.MaterialTab;
import net.runelite.client.ui.components.materialtabs.MaterialTabGroup;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.io.File;
import java.io.IOException;
import java.io.PrintWriter;

@Slf4j
public class PlayTimePanel extends PluginPanel {
    private final static Color BACKGROUND_COLOR = ColorScheme.DARK_GRAY_COLOR;

    private final PlayTimePlugin plugin;
    private final JLabel sessionTime = new JLabel();
    private final JLabel dayTime = new JLabel();
    private final JLabel weekTime = new JLabel();
    private final JLabel weekAverage = new JLabel();
    private final JLabel monthTime = new JLabel();
    private final JLabel monthAverage = new JLabel();
    private final JLabel yearTime = new JLabel();
    private final JLabel yearAverage = new JLabel();
    private final JLabel totalTrackedTime = new JLabel();
    private final JLabel totalTrackedAverage = new JLabel();
    private final JLabel externalTime = new JLabel();
    private final JLabel totalTime = new JLabel();

    private final JLabel mobileTotal = new JLabel();
    private final JLabel mobileAverage = new JLabel();
    private final JLabel mobileShare = new JLabel();
    private final JLabel mobileTracked = new JLabel();
    private final JLabel mobilePreInstall = new JLabel();
    private final JLabel mobileInGame = new JLabel();

    private boolean shown = false;
    private final PlayTimeChart chart;
    private final JPanel chartHolder = new JPanel(new BorderLayout());

    public PlayTimePanel(final PlayTimePlugin plugin)
    {
        super(false);
        this.plugin = plugin;
        this.chart = new PlayTimeChart(plugin);
        setBackground(BACKGROUND_COLOR);
        setLayout(new BorderLayout());
    }

    public void showView()
    {
        updateTimes();
        if (shown) {
            return;
        }
        shown = true;

        final PluginErrorPanel errorPanel = new PluginErrorPanel();
        errorPanel.setBorder(new EmptyBorder(10, 25, 10, 25));
        errorPanel.setContent("Play Time Tracker", "Time played, per character");

        final JPanel stats = new JPanel();
        stats.setLayout(new BoxLayout(stats, BoxLayout.Y_AXIS));
        stats.setBackground(BACKGROUND_COLOR);
        stats.setBorder(new EmptyBorder(10, 12, 10, 12));

        addPrimary(stats, sessionTime);
        addPrimary(stats, dayTime);
        stats.add(Box.createVerticalStrut(10));
        addPrimary(stats, weekTime);
        addSub(stats, weekAverage);
        stats.add(Box.createVerticalStrut(10));
        addPrimary(stats, monthTime);
        addSub(stats, monthAverage);
        stats.add(Box.createVerticalStrut(10));
        addPrimary(stats, yearTime);
        addSub(stats, yearAverage);
        stats.add(Box.createVerticalStrut(10));
        addPrimary(stats, totalTrackedTime);
        addSub(stats, totalTrackedAverage);
        stats.add(Box.createVerticalStrut(10));
        addPrimary(stats, externalTime);
        addPrimary(stats, totalTime);

        chartHolder.setBackground(BACKGROUND_COLOR);
        chartHolder.setBorder(new EmptyBorder(12, 0, 0, 0));
        chartHolder.add(chart, BorderLayout.CENTER);
        chartHolder.setAlignmentX(Component.LEFT_ALIGNMENT);
        stats.add(chartHolder);

        // Mobile tab: everything the plugin knows that did NOT happen in this client.
        final JPanel mobile = new JPanel();
        mobile.setLayout(new BoxLayout(mobile, BoxLayout.Y_AXIS));
        mobile.setBackground(BACKGROUND_COLOR);
        mobile.setBorder(new EmptyBorder(10, 12, 10, 12));

        addPrimary(mobile, mobileTotal);
        addSub(mobile, mobileAverage);
        mobile.add(Box.createVerticalStrut(10));
        addPrimary(mobile, mobileShare);
        addSub(mobile, mobileTracked);
        mobile.add(Box.createVerticalStrut(10));
        addPrimary(mobile, mobilePreInstall);
        addSub(mobile, mobileInGame);
        mobile.add(Box.createVerticalStrut(12));

        final JLabel mobileNote = new JLabel("<html><body style='width:158px'>"
                + "Off-client time is the gap between the game's own Time Played and what this "
                + "plugin tracked - mobile, other clients, or the plugin switched off. It also "
                + "picks up logging in and loading, which the game counts and this plugin does "
                + "not, so expect a little even if you never leave the client. Reported to the "
                + "minute, because the game's total is. Needs 'Count time outside RuneLite' on."
                + "</body></html>");
        mobileNote.setForeground(Color.GRAY);
        mobileNote.setAlignmentX(Component.LEFT_ALIGNMENT);
        mobile.add(mobileNote);

        final JScrollPane timeTab = wrapContainer(stats);
        final JScrollPane mobileTab = wrapContainer(mobile);
        // Do NOT hide the unselected tab: MaterialTabGroup.select swaps the display's children
        // with removeAll/add and never restores visibility, so a hidden tab stays blank forever.

        final JPanel tabContent = new JPanel(new BorderLayout());
        tabContent.setBackground(BACKGROUND_COLOR);
        tabContent.add(timeTab, BorderLayout.CENTER);

        final MaterialTabGroup tabGroup = new MaterialTabGroup(tabContent);
        tabGroup.setBorder(new EmptyBorder(4, 12, 0, 12));
        final MaterialTab timeTabButton = new MaterialTab("Play time", tabGroup, timeTab);
        final MaterialTab mobileTabButton = new MaterialTab("Mobile", tabGroup, mobileTab);
        tabGroup.addTab(timeTabButton);
        tabGroup.addTab(mobileTabButton);
        tabGroup.select(timeTabButton);

        final JButton exportButton = new JButton("Export daily CSV");
        exportButton.setAlignmentX(Component.CENTER_ALIGNMENT);
        exportButton.addActionListener(e -> exportCsv());

        final JButton resetButton = new JButton("Reset session counter");
        resetButton.setAlignmentX(Component.CENTER_ALIGNMENT);
        resetButton.addActionListener(e -> plugin.resetCounter());

        final JPanel buttons = new JPanel();
        buttons.setLayout(new BoxLayout(buttons, BoxLayout.Y_AXIS));
        buttons.setBackground(BACKGROUND_COLOR);
        buttons.setBorder(new EmptyBorder(6, 12, 10, 12));
        buttons.add(exportButton);
        buttons.add(Box.createVerticalStrut(6));
        buttons.add(resetButton);

        final JPanel header = new JPanel(new BorderLayout());
        header.setBackground(BACKGROUND_COLOR);
        header.add(errorPanel, BorderLayout.NORTH);
        header.add(tabGroup, BorderLayout.SOUTH);

        add(header, BorderLayout.NORTH);
        add(tabContent, BorderLayout.CENTER);
        add(buttons, BorderLayout.SOUTH);

        revalidate();
        repaint();
    }

    private static void addPrimary(final JPanel panel, final JLabel label)
    {
        label.setAlignmentX(Component.LEFT_ALIGNMENT);
        label.setBorder(new EmptyBorder(3, 0, 3, 0));
        panel.add(label);
    }

    private static void addSub(final JPanel panel, final JLabel label)
    {
        label.setAlignmentX(Component.LEFT_ALIGNMENT);
        label.setBorder(new EmptyBorder(0, 14, 3, 0));
        label.setForeground(Color.LIGHT_GRAY);
        panel.add(label);
    }

    public void updateTimes()
    {
        final boolean wantChart = plugin.getConfig().showChart();
        if (chartHolder.isVisible() != wantChart) {
            chartHolder.setVisible(wantChart);
        }
        if (wantChart) {
            chart.refresh();
        }

        if (plugin.getSessionTicks() == 0) {
            sessionTime.setText("Login for times to be displayed");
            dayTime.setText("");
            weekTime.setText("");
            weekAverage.setText("");
            monthTime.setText("");
            monthAverage.setText("");
            yearTime.setText("");
            yearAverage.setText("");
            totalTrackedTime.setText("");
            totalTrackedAverage.setText("");
            externalTime.setText("");
            totalTime.setText("");
            return;
        }

        updateMobile();

        final PlayTimeRecord rec = plugin.getCurrentRecord();
        sessionTime.setText("Session: " + (rec != null ? plugin.formatTicks(plugin.getSessionTicks()) : "?"));
        dayTime.setText("Today: " + (rec != null ? plugin.formatTicks(plugin.getTodayTicks()) : "?"));

        if (rec == null) {
            weekTime.setText("This week: ?");
            monthTime.setText("This month: ?");
            yearTime.setText("This year: ?");
            totalTrackedTime.setText("Total tracked: ?");
            externalTime.setText("External/mobile: ?");
            totalTime.setText("Total (in-game): ?");
            if (plugin.getConfig().showAverages()) {
                weekAverage.setText("avg/day this week: ?");
                monthAverage.setText("avg/day this month: ?");
                yearAverage.setText("avg/day this year: ?");
                totalTrackedAverage.setText("avg/day tracked: ?");
            } else {
                clearAverages();
            }
            return;
        }

        weekTime.setText("This week: " + plugin.formatTicks(plugin.getWeekTicks()));
        monthTime.setText("This month: " + plugin.formatTicks(plugin.getMonthTicks()));
        yearTime.setText("This year: " + plugin.formatTicks(plugin.getYearTicks()));
        totalTrackedTime.setText("Total tracked: " + plugin.formatTicks(plugin.getTrackedTicks()));
        externalTime.setText("External/mobile: " + plugin.formatTicks(plugin.getExternalSinceInstallTicks()));
        totalTime.setText("Total (in-game): " + plugin.formatTicks(plugin.getTotalTicks()));

        if (plugin.getConfig().showAverages()) {
            weekAverage.setText("avg/day this week: " + plugin.formatTicks(plugin.getWeekAvgTicks()));
            monthAverage.setText("avg/day this month: " + plugin.formatTicks(plugin.getMonthAvgTicks()));
            yearAverage.setText("avg/day this year: " + plugin.formatTicks(plugin.getYearAvgTicks()));
            totalTrackedAverage.setText("avg/day tracked: " + plugin.formatTicks(plugin.getTrackedAvgTicks()));
        } else {
            clearAverages();
        }
    }

    /** The Mobile tab. Driven off the same records, so it needs no state of its own. */
    private void updateMobile()
    {
        if (plugin.getCurrentPlayer() == null) {
            mobileTotal.setText("Off-client: log in to see");
            mobileAverage.setText("");
            mobileShare.setText("");
            mobileTracked.setText("");
            mobilePreInstall.setText("");
            mobileInGame.setText("");
            return;
        }

        if (!plugin.getConfig().countExternalTime()) {
            mobileTotal.setText("Off-client tracking is off");
            mobileAverage.setText("Enable 'Count time outside RuneLite'");
            mobileShare.setText("");
            mobileTracked.setText("");
            mobilePreInstall.setText("");
            mobileInGame.setText("");
            return;
        }

        final long external = plugin.getExternalSinceInstallTicks();
        if (external == 0) {
            mobileTotal.setText("Off-client: none detected");
            mobileAverage.setText("under a minute is not counted");
        } else {
            mobileTotal.setText("Off-client: " + plugin.formatTicks(external));
            mobileAverage.setText("avg/day: " + plugin.formatTicks(plugin.getExternalAvgTicks())
                    + "  (over " + plugin.getDaysSinceTrackingStarted() + "d)");
        }
        mobileShare.setText("Share of play: " + plugin.getExternalSharePercent() + "% off-client");
        mobileTracked.setText("in RuneLite: " + plugin.formatTicks(plugin.getTrackedTicks()));
        mobilePreInstall.setText("Before this plugin: " + plugin.formatTicks(plugin.getPreInstallTicks()));
        mobileInGame.setText("Game total: " + plugin.formatTicks(plugin.getTotalTicks()));
    }

    private void clearAverages()
    {
        weekAverage.setText("");
        monthAverage.setText("");
        yearAverage.setText("");
        totalTrackedAverage.setText("");
    }

    private void exportCsv()
    {
        final String csv = plugin.toDailyCsv();
        final String who = plugin.getCurrentPlayer() == null ? "playtime" : plugin.getCurrentPlayer();

        final JFileChooser chooser = new JFileChooser();
        chooser.setDialogTitle("Export daily play time");
        chooser.setSelectedFile(new File("playtime-" + who.replaceAll("[^a-zA-Z0-9_-]", "_") + ".csv"));
        if (chooser.showSaveDialog(this) != JFileChooser.APPROVE_OPTION) {
            return;
        }

        File file = chooser.getSelectedFile();
        if (!file.getName().toLowerCase().endsWith(".csv")) {
            file = new File(file.getParentFile(), file.getName() + ".csv");
        }
        try (PrintWriter pw = new PrintWriter(file, "UTF-8")) {
            pw.print(csv);
            JOptionPane.showMessageDialog(this, "Exported daily play time to:\n" + file.getAbsolutePath());
        }
        catch (IOException ex) {
            log.warn("Play Time Tracker CSV export failed", ex);
            JOptionPane.showMessageDialog(this, "Export failed: " + ex.getMessage(), "Export failed", JOptionPane.ERROR_MESSAGE);
        }
    }

    private JScrollPane wrapContainer(final JPanel container)
    {
        final JPanel wrapped = new JPanel(new BorderLayout());
        wrapped.add(container, BorderLayout.NORTH);
        wrapped.setBackground(BACKGROUND_COLOR);

        final JScrollPane scroller = new JScrollPane(wrapped);
        scroller.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
        scroller.getVerticalScrollBar().setPreferredSize(new Dimension(8, 0));
        scroller.setBackground(BACKGROUND_COLOR);

        return scroller;
    }
}

package com.playtimetracker;

import lombok.extern.slf4j.Slf4j;
import net.runelite.http.api.RuneLiteAPI;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.*;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;

import static net.runelite.client.RuneLite.RUNELITE_DIR;

@Slf4j
@Singleton
public class TimeRecordWriter {
    private static final String FILE_EXTENSION = ".log";
    private static final File PLAY_TIME_DIR = new File(RUNELITE_DIR, "playTime");
    private String playerName;
    /**
     * Set when a load of an existing file did not complete cleanly. While set, writes are refused:
     * the in-memory records are known to be incomplete, and this file is a full truncate-and-rewrite,
     * so saving would make a transient read failure a permanent loss of history.
     */
    private boolean lastLoadIncomplete;

    @Inject
    public TimeRecordWriter() {
        PLAY_TIME_DIR.mkdir();
    }

    public void setPlayerUsername(final String username)
    {
        playerName = sanitize(username);
    }

    /** Keeps the name filesystem-safe and never blank (a blank name would create a stray ".log"). */
    private static String sanitize(final String username)
    {
        if (username == null) {
            return "";
        }
        return username.trim().replaceAll("[^a-zA-Z0-9 _-]", "_");
    }

    public synchronized ArrayList<PlayTimeRecord> loadPlayTimeRecords()
    {
        if (playerName == null || playerName.isEmpty()) {
            return new ArrayList();
        }
        final String fileName = playerName.trim() + FILE_EXTENSION;
        final File file = new File(PLAY_TIME_DIR, fileName);
        final ArrayList<PlayTimeRecord> data = new ArrayList<>();
        lastLoadIncomplete = false;
        if (!file.exists()) {
            log.debug("Play Time Tracker: no existing file {}, starting fresh", fileName);
            return new ArrayList();
        }
        int lineNo = 0;
        int badLines = 0;
        boolean readFailed = false;
        try (final BufferedReader br = new BufferedReader(new FileReader(file)))
        {
            String line;
            while ((line = br.readLine()) != null)
            {
                lineNo++;
                // Skips the empty line at end of file
                if (line.length() > 0)
                {
                    try
                    {
                        final PlayTimeRecord r = RuneLiteAPI.GSON.fromJson(line, PlayTimeRecord.class);
                        if (r != null)
                        {
                            data.add(r);
                        }
                    }
                    catch (RuntimeException parseError)
                    {
                        // A line the client never finished writing must not kill the read, and must
                        // never propagate: this runs under onGameTick, where a throw repeats forever.
                        badLines++;
                        log.warn("Play Time Tracker: unparseable line {} in {} ({}): {}",
                                lineNo, fileName,
                                isAllNul(line) ? "all-NUL, crashed mid-write" : "bad JSON",
                                isAllNul(line) ? "<" + line.length() + " NUL bytes>" : line);
                    }
                }
            }
        }
        catch (FileNotFoundException e)
        {
            log.debug("File not found: {}", fileName);
        }
        catch (IOException e)
        {
            // Partial read of a file we know exists: the records we have are incomplete.
            readFailed = true;
            log.warn("IOException for file {} after {} lines: {}", fileName, lineNo, e.getMessage());
        }

        if (badLines > 0 && data.isEmpty())
        {
            // Nothing at all survived, so there is no history left to protect. Refusing to write
            // here would brick the character forever; move the wreckage aside and start clean.
            lastLoadIncomplete = !quarantine(file, fileName);
            return new ArrayList<>();
        }

        // Some records did survive alongside a failure. Overwriting now would drop the rest of the
        // file permanently, since a save is a full rewrite — so hold off until a clean read.
        lastLoadIncomplete = badLines > 0 || readFailed;
        log.debug("Play Time Tracker: loaded {} records from {} ({} lines, {} bad, incomplete={})",
                data.size(), fileName, lineNo, badLines, lastLoadIncomplete);
        return data;
    }

    /** A line of NUL bytes is what NTFS leaves behind when the client dies mid-rewrite. */
    private static boolean isAllNul(final String line)
    {
        for (int i = 0; i < line.length(); i++)
        {
            if (line.charAt(i) != '\0')
            {
                return false;
            }
        }
        return true;
    }

    /** Moves an unreadable file aside so it is never silently destroyed. True if it is now safe to write. */
    private static boolean quarantine(final File file, final String fileName)
    {
        final File dest = new File(PLAY_TIME_DIR, fileName + ".corrupt-" + System.currentTimeMillis());
        try
        {
            Files.move(file.toPath(), dest.toPath(), StandardCopyOption.REPLACE_EXISTING);
            log.warn("Play Time Tracker: {} held no readable records; moved to {} and starting fresh",
                    fileName, dest.getName());
            return true;
        }
        catch (IOException e)
        {
            log.warn("Play Time Tracker: could not quarantine {}: {}", fileName, e.getMessage());
            return false;
        }
    }

    public synchronized boolean writePlayTimeFile(final ArrayList<PlayTimeRecord> times)
    {
        if (playerName == null || playerName.isEmpty()) {
            return false;
        }
        final String fileName = playerName.trim() + FILE_EXTENSION;
        if (lastLoadIncomplete)
        {
            // Refuse to overwrite a file we failed to read in full — see lastLoadIncomplete.
            log.warn("Play Time Tracker: refusing to write {}, last load was incomplete", fileName);
            return false;
        }
        final File timeFile = new File(PLAY_TIME_DIR, fileName);
        final File tempFile = new File(PLAY_TIME_DIR, fileName + ".tmp");

        try
        {
            // Write to a temp file and swap it in, so a crash mid-save cannot leave the real file
            // truncated. This runs every 10 ticks, so the truncate window would otherwise be constant.
            final FileOutputStream fos = new FileOutputStream(tempFile, false);
            try (final BufferedWriter file = new BufferedWriter(new OutputStreamWriter(fos)))
            {
                for (final PlayTimeRecord rec : times)
                {
                    // Convert entry to JSON
                    final String dataAsString = RuneLiteAPI.GSON.toJson(rec);
                    file.append(dataAsString);
                    file.newLine();
                }
                // Force the bytes to the platter before the swap. Without this the rename can be
                // journalled ahead of the data, and a power cut leaves the real file the right
                // length but full of NULs — which is exactly the crash this method exists to stop.
                file.flush();
                fos.getFD().sync();
            }

            try
            {
                Files.move(tempFile.toPath(), timeFile.toPath(),
                        StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
            }
            catch (AtomicMoveNotSupportedException notAtomic)
            {
                Files.move(tempFile.toPath(), timeFile.toPath(), StandardCopyOption.REPLACE_EXISTING);
            }

            return true;
        }
        catch (IOException ioe)
        {
            log.warn("Error rewriting play time data to file {}: {}", fileName, ioe.getMessage());
            return false;
        }
    }
}

package com.playtimetracker;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
